// Generated by /ship test audit (Claude Opus 5.5) — 2026-10-15
// Value: protects=/coaching/form/[token] tells search engines not to index or follow the token page (it opens without a session and names the child), shows the final screen for a used, expired, revoked or unknown token (and for an empty read) without any form, a reload screen without the "new link" note when the read fails, and for an active token renders the form titled from the RPC under "Toán Thầy Vinh · <given name>" with its questions in order;
// fails_when=the robots metadata is dropped or flipped (token URLs carrying the child's full name become indexable), a non-active state renders the form or another state's message, a failed read shows the final "invalid" screen (the parent would ask for a new link, revoking a working one), a null/empty RPC result crashes instead of reading as invalid, the brand line shows the student's full name (a misdirected link would reveal another family's child) or loses the given name, or the questions lose their order, numbering or required flag on the way from the RPC rows;
// why_new=step 11b moves the state screen into public-coaching-form-shell, adds the noindex metadata and passes student_name; the form, shell and preview tests render the components directly and no test loaded the route;
// seam=createSupabaseServerClient is mocked at its module boundary with an rpc stub; the submit action module is mocked so nothing can be sent; no_claim=does not prove get_public_coaching_form's SQL (states, student_name, order by sort_order) nor that Next emits the robots meta tag (only the exported metadata object)
import { cleanup, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import PublicCoachingFormPage, { metadata } from "@/app/coaching/form/[token]/page";
import { submitPublicCoachingFormAction } from "@/features/coaching/actions/public-coaching-form-actions";
import { getStudentGivenName } from "@/features/coaching/components/public-coaching-form-shell";

const rpc = vi.hoisted(() => vi.fn());

vi.mock("@/lib/supabase/server", () => ({
  createSupabaseServerClient: vi.fn(async () => ({ rpc })),
}));
vi.mock("@/features/coaching/actions/public-coaching-form-actions", () => ({
  submitPublicCoachingFormAction: vi.fn(),
}));

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

const TOKEN = "t".repeat(48);
const FINAL_NOTE = "Liên hệ trung tâm nếu cần một liên kết mới.";

/** A row as get_public_coaching_form returns it for a non-active link: only the state is set. */
const stateRow = (state: string) => ({
  configuration: null,
  form_title: null,
  form_version_id: null,
  instructions: null,
  is_required: null,
  question_description: null,
  question_id: null,
  question_title: null,
  question_type: null,
  sort_order: null,
  state,
  student_name: null,
});

const activeRow = {
  ...stateRow("active"),
  form_title: "Phiếu phản hồi tháng 10",
  form_version_id: "00000000-0000-4000-8000-000000000010",
  instructions: "Phụ huynh điền trong khoảng 3 phút.",
  student_name: "Bùi Quang Minh",
};

async function renderRoute() {
  render(await PublicCoachingFormPage({ params: Promise.resolve({ token: TOKEN }) }));
}

describe("/coaching/form/[token] route", () => {
  it("keeps every token page out of search indexes", () => {
    expect(metadata.robots).toEqual({ follow: false, index: false });
  });

  it.each([
    ["submitted", "Phiếu này đã được gửi."],
    ["expired", "Liên kết đã hết hạn."],
    ["revoked", "Liên kết không còn hiệu lực."],
    ["invalid", "Liên kết không hợp lệ."],
  ])("shows the %s screen and no form", async (state, message) => {
    rpc.mockResolvedValue({ data: [stateRow(state)], error: null });
    await renderRoute();

    expect(rpc).toHaveBeenCalledWith("get_public_coaching_form", { p_token: TOKEN });
    expect(screen.getByRole("heading", { level: 1, name: message })).toBeInTheDocument();
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    expect(screen.getByText(FINAL_NOTE)).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Gửi phiếu" })).not.toBeInTheDocument();
    // A final state: reloading cannot help.
    expect(screen.queryByRole("link", { name: "Tải lại trang" })).not.toBeInTheDocument();
  });

  // A failed read says nothing about the link: the final "invalid" screen would send the parent to ask for a
  // new link, and issuing one revokes the link that still works.
  it("shows a reload screen, not the final one, when the read fails", async () => {
    rpc.mockResolvedValue({ data: null, error: { message: "boom" } });
    await renderRoute();
    expect(screen.getByRole("heading", { level: 1, name: "Chưa tải được phiếu." })).toBeInTheDocument();
    expect(screen.getByText("Vui lòng tải lại trang sau ít phút.")).toBeInTheDocument();
    expect(screen.queryByText(FINAL_NOTE)).not.toBeInTheDocument();
    expect(screen.queryByText(/liên kết mới/)).not.toBeInTheDocument();
    expect(screen.queryByRole("heading", { name: "Liên kết không hợp lệ." })).not.toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Gửi phiếu" })).not.toBeInTheDocument();
    // A full reload of the same token page reads the link again.
    expect(screen.getByRole("link", { name: "Tải lại trang" })).toHaveAttribute("href", `/coaching/form/${TOKEN}`);
    cleanup();

    // The token goes into the path encoded.
    render(await PublicCoachingFormPage({ params: Promise.resolve({ token: "a b/c?d" }) }));
    expect(screen.getByRole("link", { name: "Tải lại trang" })).toHaveAttribute("href", "/coaching/form/a%20b%2Fc%3Fd");
  });

  it("reads an empty or missing RPC result as an invalid link", async () => {
    rpc.mockResolvedValue({ data: [], error: null });
    await renderRoute();
    expect(screen.getByRole("heading", { level: 1, name: "Liên kết không hợp lệ." })).toBeInTheDocument();
    expect(screen.getByText(FINAL_NOTE)).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: "Gửi phiếu" })).not.toBeInTheDocument();
    cleanup();

    rpc.mockResolvedValue({ data: null, error: null });
    await renderRoute();
    expect(screen.getByRole("heading", { level: 1, name: "Liên kết không hợp lệ." })).toBeInTheDocument();
  });

  it.each([
    ["a single-word name", "Minh", "Toán Thầy Vinh · Minh"],
    ["extra spaces", "  Nguyễn   Thị  Lan  ", "Toán Thầy Vinh · Lan"],
    ["a blank name", "   ", "Toán Thầy Vinh"],
    ["no name", null, "Toán Thầy Vinh"],
  ])("names the student by the given name only, for %s", async (_label, studentName, brandLine) => {
    rpc.mockResolvedValue({
      data: [{ ...activeRow, question_id: "00000000-0000-4000-8000-000000000001", question_title: "Ghi chú", question_type: "short_text", sort_order: 1, student_name: studentName }],
      error: null,
    });
    await renderRoute();
    expect(screen.getByText(brandLine, { exact: true })).toBeInTheDocument();
  });

  it("reads the given name as the last word of the full name", () => {
    expect(getStudentGivenName("Bùi Quang Minh")).toBe("Minh");
    expect(getStudentGivenName("Minh")).toBe("Minh");
    expect(getStudentGivenName(" Lê\tVăn\nAn ")).toBe("An");
    expect(getStudentGivenName("")).toBeNull();
    expect(getStudentGivenName("   ")).toBeNull();
    expect(getStudentGivenName(null)).toBeNull();
    expect(getStudentGivenName(undefined)).toBeNull();
  });

  it("renders an active link's form under the student's name with its questions in order", async () => {
    rpc.mockResolvedValue({
      data: [
        {
          ...activeRow,
          configuration: { options: ["Có", "Không"] },
          is_required: true,
          question_description: null,
          question_id: "00000000-0000-4000-8000-000000000001",
          question_title: "Con có làm bài tập về nhà?",
          question_type: "single_choice",
          sort_order: 1,
        },
        {
          ...activeRow,
          configuration: {},
          is_required: false,
          question_description: "Điều phụ huynh muốn trung tâm biết.",
          question_id: "00000000-0000-4000-8000-000000000002",
          question_title: "Ghi chú thêm",
          question_type: "short_text",
          sort_order: 2,
        },
      ],
      error: null,
    });
    await renderRoute();

    // The given name only: the page opens without a session, so a misdirected link must not show the full name.
    expect(screen.getByText("Toán Thầy Vinh · Minh")).toBeInTheDocument();
    expect(screen.queryByText(/Bùi Quang/)).not.toBeInTheDocument();
    expect(screen.getByRole("heading", { level: 1, name: "Phiếu phản hồi tháng 10" })).toBeInTheDocument();
    expect(screen.getByText("Phụ huynh điền trong khoảng 3 phút.")).toBeInTheDocument();
    // jsdom trims the sr-only " (bắt buộc)" span's leading space that browsers keep.
    const attended = screen.getByRole("group", { name: /^1\. Con có làm bài tập về nhà\?\s*\(bắt buộc\)$/ });
    expect(within(attended).getAllByRole("radio").map((radio) => radio.getAttribute("value"))).toEqual(["Có", "Không"]);
    const note = screen.getByRole("group", { name: "2. Ghi chú thêm" });
    expect(within(note).getByRole("textbox")).toBeInTheDocument();
    expect(within(note).getByText("Điều phụ huynh muốn trung tâm biết.")).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Gửi phiếu" })).toBeEnabled();
    expect(screen.queryByText(FINAL_NOTE)).not.toBeInTheDocument();
    expect(submitPublicCoachingFormAction).not.toHaveBeenCalled();
  });
});
